selector_to_html = {"a[href=\"#execute-transforms\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Execute Transforms<a class=\"headerlink\" href=\"#execute-transforms\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#benchmark-fft-performance\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Benchmark FFT Performance<a class=\"headerlink\" href=\"#benchmark-fft-performance\" title=\"Link to this heading\">#</a></h3><p>Examples:</p>", "a[href=\"#output\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Output<a class=\"headerlink\" href=\"#output\" title=\"Link to this heading\">#</a></h4><p>Exit code is <code class=\"docutils literal notranslate\"><span class=\"pre\">0</span></code> if all accuracy tests passed, <code class=\"docutils literal notranslate\"><span class=\"pre\">1</span></code> if any failed.</p>", "a[href=\"#usage\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Usage<a class=\"headerlink\" href=\"#usage\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#examples\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Examples<a class=\"headerlink\" href=\"#examples\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#use-the-c-api\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Use the C API<a class=\"headerlink\" href=\"#use-the-c-api\" title=\"Link to this heading\">#</a></h2><p>FlagFFT exposes a cuFFT-compatible C API in <code class=\"docutils literal notranslate\"><span class=\"pre\">include/flagfft.h</span></code>.</p>", "a[href=\"#manage-plans\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Manage Plans<a class=\"headerlink\" href=\"#manage-plans\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#run-c-tests\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Run C++ Tests<a class=\"headerlink\" href=\"#run-c-tests\" title=\"Link to this heading\">#</a></h3><p>Built with <code class=\"docutils literal notranslate\"><span class=\"pre\">-DFLAGFFT_BUILD_TESTS=ON</span></code>. Each test binary compares FlagFFT output against cuFFT using normwise relative error metrics (<code class=\"docutils literal notranslate\"><span class=\"pre\">rel_l2</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">rel_linf</span></code>).</p>", "a[href=\"#supported-features\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Supported Features<a class=\"headerlink\" href=\"#supported-features\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#flagfft-user-guide\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">FlagFFT User Guide<a class=\"headerlink\" href=\"#flagfft-user-guide\" title=\"Link to this heading\">#</a></h1><h2>Use the C API<a class=\"headerlink\" href=\"#use-the-c-api\" title=\"Link to this heading\">#</a></h2><p>FlagFFT exposes a cuFFT-compatible C API in <code class=\"docutils literal notranslate\"><span class=\"pre\">include/flagfft.h</span></code>.</p>", "a[href=\"#auto-tune-planned\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Auto-Tune (planned)<a class=\"headerlink\" href=\"#auto-tune-planned\" title=\"Link to this heading\">#</a></h3><p>Currently a placeholder; exits with <code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGFFT_NOT_SUPPORTED</span></code>.</p>", "a[href=\"#exit-codes\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Exit Codes<a class=\"headerlink\" href=\"#exit-codes\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#run-tests\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Run Tests<a class=\"headerlink\" href=\"#run-tests\" title=\"Link to this heading\">#</a></h2><p>FlagFFT has three layers of testing: a unified Python test runner, C++ unit tests (Google Test), and Python codegen tests (pytest).</p>", "a[href=\"#create-plans\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Create Plans<a class=\"headerlink\" href=\"#create-plans\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#combination-presets\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Combination Presets<a class=\"headerlink\" href=\"#combination-presets\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#test-structure\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Test Structure<a class=\"headerlink\" href=\"#test-structure\" title=\"Link to this heading\">#</a></h4><p>Suffix key: <code class=\"docutils literal notranslate\"><span class=\"pre\">s</span></code> = single-batch, <code class=\"docutils literal notranslate\"><span class=\"pre\">b</span></code> = multi-batch; <code class=\"docutils literal notranslate\"><span class=\"pre\">ct</span></code> = Cooley-Tukey, <code class=\"docutils literal notranslate\"><span class=\"pre\">bs</span></code> = Bluestein/Rader.</p>", "a[href=\"#use-the-native-cli\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Use the Native CLI<a class=\"headerlink\" href=\"#use-the-native-cli\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">flagfft-cli</span></code> is a native benchmark and verification tool. Build it with <code class=\"docutils literal notranslate\"><span class=\"pre\">-DFLAGFFT_BUILD_CLI=ON</span></code>.</p>", "a[href=\"#transform-types\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Transform Types<a class=\"headerlink\" href=\"#transform-types\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#use-the-unified-test-runner\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Use the Unified Test Runner<a class=\"headerlink\" href=\"#use-the-unified-test-runner\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">tools/run_tests.py</span></code> is the primary entry point for running the full test suite. It orchestrates both accuracy tests (C++ ctest binaries comparing FlagFFT output against cuFFT) and performance benchmarks (flagfft-cli bench).</p>", "a[href=\"#run-individual-tests\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Run Individual Tests<a class=\"headerlink\" href=\"#run-individual-tests\" title=\"Link to this heading\">#</a></h4><p>Each test binary accepts: <code class=\"docutils literal notranslate\"><span class=\"pre\">--nx</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">--batch</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">--direction</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">--scale</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">--json-file</span></code>.</p>", "a[href=\"#run-python-tests\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Run Python Tests<a class=\"headerlink\" href=\"#run-python-tests\" title=\"Link to this heading\">#</a></h3><p>Tests for the <code class=\"docutils literal notranslate\"><span class=\"pre\">flagfft_codegen</span></code> Python package. Requires the package installed (<code class=\"docutils literal notranslate\"><span class=\"pre\">pip</span> <span class=\"pre\">install</span> <span class=\"pre\">.</span></code>).</p>", "a[href=\"#configure-tests\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Configure Tests<a class=\"headerlink\" href=\"#configure-tests\" title=\"Link to this heading\">#</a></h3><p>The test parameter space is defined in <code class=\"docutils literal notranslate\"><span class=\"pre\">conf/</span></code>:</p>", "a[href=\"#data-types\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Data Types<a class=\"headerlink\" href=\"#data-types\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#planned-not-yet-supported\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Planned / Not Yet Supported<a class=\"headerlink\" href=\"#planned-not-yet-supported\" title=\"Link to this heading\">#</a></h3>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
